const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((v) => resolve(v), (e) => reject(e));
  });
}

function maskNTL(img, band) {
  // Keep only strictly positive and below a high ceiling to avoid fills/outliers.
  const ntl = img.select(band);
  const valid = ntl.gt(0).and(ntl.lt(10000));
  return img.updateMask(valid);
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Point([-95.3698, 29.7604]).buffer(20000); // ~20 km around downtown Houston
    const aprilStart = '2024-04-01';
    const mayStart = '2024-05-18';
    const aprilEnd = '2024-05-01';
    const mayEnd = '2024-05-19';

    // 2. Data Acquisition & Fallback dataset selection
    const bandDaily = 'DNB_BRDF-Corrected_NTL';
    let dailyDs = 'NOAA/VIIRS/001/VNP46A2'; // primary guess
    // Probe dataset; if fails, try alternate ID.
    try {
      // Probe a tiny call to ensure dataset ID exists.
      await getInfoAsync(ee.ImageCollection(dailyDs).limit(1).size());
    } catch (e1) {
      dailyDs = 'NASA/VIIRS/001/VNP46A2';
      try {
        await getInfoAsync(ee.ImageCollection(dailyDs).limit(1).size());
      } catch (e2) {
        console.log('Dataset error: VNP46A2 not found');
        console.log('D');
        return;
      }
    }

    // Build daily collections
    let aprilCol = ee.ImageCollection(dailyDs)
      .filterDate(aprilStart, aprilEnd)
      .filterBounds(roi)
      .map(function(img){ return maskNTL(img, bandDaily).select(bandDaily); });

    let may18Col = ee.ImageCollection(dailyDs)
      .filterDate(mayStart, mayEnd)
      .filterBounds(roi)
      .map(function(img){ return maskNTL(img, bandDaily).select(bandDaily); });

    const aprilSize = await getInfoAsync(aprilCol.size());
    const may18Size = await getInfoAsync(may18Col.size());

    // If April daily is empty, try monthly stable lights as fallback for April only
    let usedAprilMonthlyFallback = false;
    let aprilImg;
    let aprilBand = bandDaily;

    if (aprilSize === 0) {
      // Fallback to NOAA monthly VCMSLCFG (avg_rad) for April 2024
      const monthlyDs = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
      let aprilMonthly;
      try {
        aprilMonthly = ee.ImageCollection(monthlyDs)
          .filterDate(aprilStart, aprilEnd)
          .filterBounds(roi)
          .select('avg_rad');
        const mSize = await getInfoAsync(aprilMonthly.size());
        if (mSize === 0) {
          console.log('April Images: 0');
          console.log('May18 Images: ' + may18Size);
          console.log('C1');
          return;
        }
        aprilImg = aprilMonthly.mosaic().updateMask(aprilMonthly.first().select('avg_rad').gt(0));
        aprilBand = 'avg_rad';
        usedAprilMonthlyFallback = true;
      } catch (eMonthly) {
        console.log('April Images: 0');
        console.log('May18 Images: ' + may18Size);
        console.log('D');
        return;
      }
    } else {
      aprilImg = aprilCol.mean();
    }

    if (may18Size === 0) {
      console.log('April Images: ' + (usedAprilMonthlyFallback ? 'MonthlyFallback' : aprilSize));
      console.log('May18 Images: 0');
      console.log('C1');
      return;
    }

    // Build May 18 composite image
    const may18Img = may18Col.median();

    // 3. Processing: Compute counts and means
    const scale = 1000;
    const maxPixels = 1e9;

    // April stats
    const aprilMeanDict = aprilImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: roi,
      scale: scale,
      maxPixels: maxPixels
    });
    const aprilCountDict = aprilImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: scale,
      maxPixels: maxPixels
    });
    const totalCountAprilDict = ee.Image.constant(1).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: scale,
      maxPixels: maxPixels
    });

    // May 18 stats
    const mayMeanDict = may18Img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: roi,
      scale: scale,
      maxPixels: maxPixels
    });
    const mayCountDict = may18Img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: scale,
      maxPixels: maxPixels
    });
    const totalCountMayDict = ee.Image.constant(1).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: scale,
      maxPixels: maxPixels
    });

    const aprilMean = await getInfoAsync(aprilMeanDict.get(aprilBand));
    const aprilValid = await getInfoAsync(aprilCountDict.get(aprilBand));
    const aprilTotal = await getInfoAsync(totalCountAprilDict.get('constant'));

    const mayMean = await getInfoAsync(mayMeanDict.get(bandDaily));
    const mayValid = await getInfoAsync(mayCountDict.get(bandDaily));
    const mayTotal = await getInfoAsync(totalCountMayDict.get('constant'));

    // 4. Validation & Edge Cases
    if (!aprilValid || aprilValid === 0 || !mayValid || mayValid === 0) {
      console.log(`April Images: ${usedAprilMonthlyFallback ? 'MonthlyFallback' : aprilSize}`);
      console.log(`May18 Images: ${may18Size}`);
      console.log('Valid px (Apr/May18): ' + (aprilValid || 0) + '/' + (mayValid || 0));
      console.log('C2');
      return;
    }
    const isInvalid = (v) => (v === null || v === undefined || !isFinite(v) || v < 0 || v > 10000);
    if (isInvalid(aprilMean) || isInvalid(mayMean)) {
      console.log(`April Images: ${usedAprilMonthlyFallback ? 'MonthlyFallback' : aprilSize}`);
      console.log(`May18 Images: ${may18Size}`);
      console.log('C3');
      return;
    }

    // 5. Results & Decision
    const aprilValidPct = aprilTotal ? (100 * aprilValid / aprilTotal) : 0;
    const mayValidPct = mayTotal ? (100 * mayValid / mayTotal) : 0;
    const delta = mayMean - aprilMean;
    const pctChange = (aprilMean !== 0) ? (100 * delta / aprilMean) : null;

    console.log(`April Images: ${usedAprilMonthlyFallback ? 'MonthlyFallback' : aprilSize} (mean=${aprilMean.toFixed(3)}, valid%=${aprilValidPct.toFixed(1)})`);
    console.log(`2024-05-18 Images: ${may18Size} (mean=${mayMean.toFixed(3)}, valid%=${mayValidPct.toFixed(1)})`);
    console.log(`Delta (May18 - AprMean): ${delta.toFixed(3)} (${pctChange !== null ? pctChange.toFixed(1) + '%' : 'NA'})`);

    // Final Answer
    if (mayMean < aprilMean) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
